  ('oaxaca-city-mexico', '10S', 'Oaxaca City & the Central Valleys', 'Mexico', 'High valley of mezcal and markets', 'live', 'verified', 'kyoto', 'Oaxaca (Oaxaca City & Coast)', '{"romance","expedition"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["Dual UNESCO World Heritage: Historic Centre of Oaxaca + Monte Alban, jointly inscribed 1987","Santiago Matatlan is the recognized World Capital of Mezcal, ~45 min SE on the Ruta Caminos del Mezcal","Teotitlan del Valle: ~2,500-year living Zapotec weaving tradition, natural cochineal/indigo/marigold dyes, rugs $75–$500","Tlacolula Sunday market: longest continuously running market in Mesoamerica, 1,000+ vendors","El Tule (Santa Maria del Tule): the world''s widest tree, a ~2,000-year-old Montezuma cypress"],"safety":{"emergency":"911","hospitals":["Clinica Hospital Carmen (Calle M. Abasolo 215)","Hospital Reforma (Calle Reforma 613)"],"medevac":"Air ambulance staged at OAX; serious cases transferred to Mexico City (MEX)","advisory_level":"L2","advisory_note":"State-wide Level 2; Oaxaca City / Monte Alban / Puerto Escondido / Huatulco explicitly carry no US-gov-employee restrictions","book_enabled":true,"tourist_zone_carveout":true,"air_access_verified":true,"airport":"OAX (Xoxocotlan International)","altitude_m":1555,"altitude_note":"~1,550–1,555 m (mild)","water":"bottled/purified","other_risks":["Hierve el Agua cliff-edge footing + periodic Jun–Oct closures","high-proof mezcal + rural driving (use driver)","high-valley UV/heat on all-day circuits"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all but essential travel","text":"advises against all but essential travel State of Baja California FCDO advises against all but essential travel to the city of Tijuana, except: airside transit through Tijuana airport the Cross Border Xpress bridge from the airport linking terminals across the Mexican-US border the federal toll road 1D and Via Rápida through Tijuana to the border 